/**
 * @suppress
 */
public object FfiConverterTypeMobileCore: FfiConverter<MobileCore, Pointer> {

    override fun lower(value: MobileCore): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): MobileCore {
        return MobileCore(value)
    }

    override fun read(buf: ByteBuffer): MobileCore {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: MobileCore) = 8UL

    override fun write(value: MobileCore, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



