sealed class MobileException: kotlin.Exception() {
    
    class Io(
        
        val v1: kotlin.String
        ) : MobileException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Invalid(
        
        val v1: kotlin.String
        ) : MobileException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Corrupt(
        
        val v1: kotlin.String
        ) : MobileException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class NotFound(
        
        val v1: kotlin.String
        ) : MobileException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class RuleInputInvalid(
        
        val v1: kotlin.String
        ) : MobileException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class SubscriptionInvalid(
        
        val v1: kotlin.String
        ) : MobileException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * contract v0.1：查询句柄已淘汰
     */
    class StaleToken(
        
        val v1: kotlin.String
        ) : MobileException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * contract v0.1：subscription_not_found
     */
    class SubscriptionNotFound(
        
        val v1: kotlin.String
        ) : MobileException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * 进度回调返回 false
     */
    class Cancelled(
        ) : MobileException() {
        override val message
            get() = ""
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<MobileException> {
        override fun lift(error_buf: RustBuffer.ByValue): MobileException = FfiConverterTypeMobileError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeMobileError : FfiConverterRustBuffer<MobileException> {
    override fun read(buf: ByteBuffer): MobileException {
        

        return when(buf.getInt()) {
            1 -> MobileException.Io(
                FfiConverterString.read(buf),
                )
            2 -> MobileException.Invalid(
                FfiConverterString.read(buf),
                )
            3 -> MobileException.Corrupt(
                FfiConverterString.read(buf),
                )
            4 -> MobileException.NotFound(
                FfiConverterString.read(buf),
                )
            5 -> MobileException.RuleInputInvalid(
                FfiConverterString.read(buf),
                )
            6 -> MobileException.SubscriptionInvalid(
                FfiConverterString.read(buf),
                )
            7 -> MobileException.StaleToken(
                FfiConverterString.read(buf),
                )
            8 -> MobileException.SubscriptionNotFound(
                FfiConverterString.read(buf),
                )
            9 -> MobileException.Cancelled()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: MobileException): ULong {
        return when(value) {
            is MobileException.Io -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is MobileException.Invalid -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is MobileException.Corrupt -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is MobileException.NotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is MobileException.RuleInputInvalid -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is MobileException.SubscriptionInvalid -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is MobileException.StaleToken -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is MobileException.SubscriptionNotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is MobileException.Cancelled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: MobileException, buf: ByteBuffer) {
        when(value) {
            is MobileException.Io -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is MobileException.Invalid -> {
                buf.putInt(2)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is MobileException.Corrupt -> {
                buf.putInt(3)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is MobileException.NotFound -> {
                buf.putInt(4)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is MobileException.RuleInputInvalid -> {
                buf.putInt(5)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is MobileException.SubscriptionInvalid -> {
                buf.putInt(6)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is MobileException.StaleToken -> {
                buf.putInt(7)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is MobileException.SubscriptionNotFound -> {
                buf.putInt(8)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is MobileException.Cancelled -> {
                buf.putInt(9)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





/**
 * 建库进度回调（平台实现）。返回 false = 取消。会在后台线程调用。
 */
public interface BuildProgress {
    
    fun `onProgress`(`phase`: BuildPhase, `done`: kotlin.ULong, `total`: kotlin.ULong): kotlin.Boolean
    
    companion object
}

// Magic number for the Rust proxy to call using the same mechanism as every other method,
// to free the callback once it's dropped by Rust.
internal const val IDX_CALLBACK_FREE = 0
// Callback return codes
internal const val UNIFFI_CALLBACK_SUCCESS = 0
internal const val UNIFFI_CALLBACK_ERROR = 1
internal const val UNIFFI_CALLBACK_UNEXPECTED_ERROR = 2

/**
 * @suppress
 */
public abstract class FfiConverterCallbackInterface<CallbackInterface: Any>: FfiConverter<CallbackInterface, Long> {
    internal val handleMap = UniffiHandleMap<CallbackInterface>()

    internal fun drop(handle: Long) {
        handleMap.remove(handle)
    }

    override fun lift(value: Long): CallbackInterface {
        return handleMap.get(value)
    }

    override fun read(buf: ByteBuffer) = lift(buf.getLong())

    override fun lower(value: CallbackInterface) = handleMap.insert(value)

    override fun allocationSize(value: CallbackInterface) = 8UL

    override fun write(value: CallbackInterface, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}

// Put the implementation in an object so we don't pollute the top-level namespace
internal object uniffiCallbackInterfaceBuildProgress {
    internal object `onProgress`: UniffiCallbackInterfaceBuildProgressMethod0 {
        override fun callback(`uniffiHandle`: Long,`phase`: RustBuffer.ByValue,`done`: Long,`total`: Long,`uniffiOutReturn`: ByteByReference,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeBuildProgress.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`onProgress`(
                    FfiConverterTypeBuildPhase.lift(`phase`),
                    FfiConverterULong.lift(`done`),
                    FfiConverterULong.lift(`total`),
                )
            }
            val writeReturn = { value: kotlin.Boolean -> uniffiOutReturn.setValue(FfiConverterBoolean.lower(value)) }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeBuildProgress.handleMap.remove(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceBuildProgress.UniffiByValue(
        `onProgress`,
        uniffiFree,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
    internal fun register(lib: UniffiLib) {
        lib.uniffi_zephyr_mobile_core_fn_init_callback_vtable_buildprogress(vtable)
    }
}

